// Pure logic for the "Rx in a minute" reference guide (src/screens/RxGuide.jsx): section kinds, search and filters.
// No React / DOM / storage. The guide text itself lives in data.js (generated by scripts/build-rx-guide.mjs) and is
// shown exactly as written; nothing here rewrites, merges or computes a dose.
import { foldText } from '../search/text.js';

// Order the sections are shown in on a card, with the marker used in the source guide.
export const KIND_ORDER = Object.freeze(['check', 'rx', 'warn', 'avoid', 'follow']);
export const KIND_ICON = Object.freeze({ check: '🔎', rx: '💊', warn: '⚠️', avoid: '⛔', follow: '📅' });

// Folded text of a card, built once per card object (the data is immutable).
const cache = new WeakMap();
function haystack(card) {
  let h = cache.get(card);
  if (!h) {
    h = {
      title: foldText(`${card.num} ${card.title}`),
      all: foldText(`${card.num} ${card.title} ${card.sections.map(s => s.lines.join(' ')).join(' ')}`)
    };
    cache.set(card, h);
  }
  return h;
}

// Every word of the query must appear somewhere in the card (Arabic spelling variants and Arabic-Indic digits are
// folded, so "فطريه" finds "فطرية"). Cards whose title holds all the words come first; otherwise original order.
export function searchCards(cards, { query = '', chapter = null, urgentOnly = false } = {}) {
  const words = foldText(query).split(' ').filter(Boolean);
  const out = [];
  (cards || []).forEach((card, index) => {
    if (chapter != null && card.chapter !== chapter) return;
    if (urgentOnly && !card.urgent) return;
    const h = haystack(card);
    if (!words.every(w => h.all.includes(w))) return;
    out.push({ card, index, rank: words.length && words.every(w => h.title.includes(w)) ? 0 : 1 });
  });
  out.sort((a, b) => a.rank - b.rank || a.index - b.index);
  return out.map(x => x.card);
}

// How many cards each chapter holds: { 3: 21, 4: 31, ... }.
export function chapterCounts(cards) {
  const counts = {};
  for (const c of cards || []) counts[c.chapter] = (counts[c.chapter] || 0) + 1;
  return counts;
}

// A card's sections in display order, skipping empty ones.
export const orderedSections = card => KIND_ORDER
  .map(kind => ({ kind, lines: (card.sections.find(s => s.kind === kind) || { lines: [] }).lines }))
  .filter(s => s.lines.length);
